pdcm_dp_unit dut (
    .clk(clk),
    .op_en(op_en),
    .write_en(write_en),
    .iact(iact),
    .write_data(write_data),
    .oact(oact)
);

task automatic write_weights();
    @(posedge clk);
    for (int witn = 0; witn < BW*2; witn++) begin
        write_en <= '0;
        write_en[witn] <= 1; 
        if (witn[0]) begin
            for (int k = 0; k < (N / 2); k++) begin
                write_data[k] <= weights[2*k+1][witn/2];
            end
        end else begin
            for (int k = 0; k < (N / 2); k++) begin
                write_data[k] <= weights[2*k][witn/2];
            end
        end
        // write_data <= '1;
        @(posedge clk);
    end
    write_en <= '0;
endtask //automatic

