task automatic inference();
    int op_counter = 0;
    act_counter ='0;
    @(posedge clk);
    op_en <= '1;
    @(posedge clk);
    op_en <= '1;
    for (int opint = 0; opint < 105; opint++) begin
        if (opint >= 0) begin
            for (int j = 0; j < N; ++j) begin
                iact[j] <= inputs[opint][j][0];
                iact[N + j] <= inputs[opint][j][1];
            end
        end
        if (opint >= 1) begin
            for (int j = 0; j < N; ++j) begin
                iact[2*N + j] <= inputs[opint - 1][j][2];
                iact[3*N + j] <= inputs[opint - 1][j][3];
            end
        end
        if (opint >= 2) begin
            for (int j = 0; j < N; ++j) begin
                iact[4*N + j] <= inputs[opint - 2][j][4];
                iact[5*N + j] <= inputs[opint - 2][j][5];
            end
        end
        if (opint >= 3) begin
            for (int j = 0; j < N; ++j) begin
                iact[6*N + j] <= inputs[opint - 3][j][6];
                iact[7*N + j] <= inputs[opint - 3][j][7];
            end
        end 
        if (opint >= 5) begin
            act_counter <= act_counter + 1;
        end
        fork
            if (opint >= 5) begin
                    #10ps;
                    if ($signed(oact) != $signed(outputs[act_counter])) begin
                    $error("Output mismatch at time %0t; expected %d, get %d", $time, $signed(outputs[act_counter]), $signed(oact));
                end
            end
            join
        @(posedge clk); 
    end
endtask //automatic
always begin : CLOCK_GENERATION
#1  clk = ~clk;
end
initial begin: CLOCK_INITIALIZATION
    clk = '0;
end 

initial begin: TEST_VECTORS
    op_en = '0;
    write_en = '0;
    write_data = '0;
    iact = '0;
    act_counter = 1;
    @(posedge clk);
    write_weights();
    @(posedge clk);
    inference();
    repeat (100) @(posedge clk);
    $finish;
end
endmodule